{
 "summary": "Two non-existence (breakdown) statements are formalized for ν > 0. On ℝ³ (alternative C), there exist a smooth, divergence-free, rapidly decaying u₀ and a smooth, rapidly decaying force f such that no smooth (v,p) on ℝ³×[0,∞) solves Navier–Stokes with v(t) ∈ L² and uniformly bounded energy. On the torus (alternative D), there exist periodic data for which no smooth, spatially periodic global solution exists. The most important caveat: the periodic theorem quantifies only over natural-number viscosities (`nu : ℕ`), while the paper's Corollary 10.6 is stated for every real ν > 0.",
 "glossary": [
  {"decl": "divergence", "line": 81, "plain": "∇·v(x) = trace of the Jacobian Dv(x); it is 0 if v is not differentiable at x", "standard_concept": "divergence", "matches_standard": "yes", "note": "The junk value never matters here, because every field it is applied to is smooth."},
  {"decl": "IsOnePeriodic", "line": 121, "plain": "f(x+e_i) = f(x) for all x and every coordinate i", "standard_concept": "function on ℝⁿ/ℤⁿ", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityCondition", "line": 134, "plain": "u₀ is C^∞ and ∇·u₀ = 0 everywhere", "standard_concept": "Fefferman's conditions on u°", "matches_standard": "yes", "note": ""},
  {"decl": "InitialVelocityConditionDecay", "line": 150, "plain": "In addition, for all m and K there is C with ‖D^m u₀(x)‖ ≤ C(1+|x|)^{-K}", "standard_concept": "Fefferman condition (4)", "matches_standard": "yes", "note": "The base of the power is ≥ 1, so the real power is well behaved."},
  {"decl": "InitialVelocityConditionPeriodic", "line": 164, "plain": "Smooth, divergence-free and 1-periodic u₀", "standard_concept": "Fefferman condition (8)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceCondition", "line": 175, "plain": "f is C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth force", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionDecay", "line": 185, "plain": "In addition, ‖D^m_{x,t} f(x,t)‖ ≤ C(1+|x|+t)^{-K} for t ≥ 0", "standard_concept": "Fefferman condition (5)", "matches_standard": "yes", "note": ""},
  {"decl": "ForceConditionPeriodic", "line": 200, "plain": "Smooth f, 1-periodic in x for t ≥ 0, with ‖D^m f‖ ≤ C(1+t)^{-K}", "standard_concept": "Fefferman conditions (8),(9)", "matches_standard": "yes", "note": ""},
  {"decl": "NavierStokesExistenceAndSmoothness", "line": 217, "plain": "For t ≥ 0: ∂_t v + (v·∇)v = νΔv − ∇p + f (one-sided time derivative at t = 0), ∇·v = 0, v(·,0) = u₀, and v and p are C^∞ on ℝⁿ×[0,∞)", "standard_concept": "smooth global solution (Fefferman (1)-(3),(6))", "matches_standard": "yes", "note": "Smoothness makes all derivatives genuine, so no junk values arise."},
  {"decl": "NavierStokesExistenceAndSmoothnessRn", "line": 245, "plain": "In addition, v(t) ∈ L² for each t ≥ 0 and sup_t ∫|v|² < ∞", "standard_concept": "Fefferman condition (7)", "matches_standard": "yes", "note": "The MemLp field rules out the junk-integral loophole."},
  {"decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 262, "plain": "In addition, v(·,t) and p(·,t) are 1-periodic for t ≥ 0", "standard_concept": "Fefferman (10),(11) plus the errata", "matches_standard": "yes", "note": "Pressure periodicity follows the Clay errata."}
 ],
 "lean_claims": [
  {"theorem": "navier_stokes_breakdown_R3", "line": 273, "plain": "For every real ν > 0 there exist u₀, f: ℝ³ satisfying (4),(5), smooth and divergence-free, such that no (v,p) is a smooth global solution with v(t) ∈ L² and uniformly bounded energy."},
  {"theorem": "navier_stokes_breakdown_periodic", "line": 280, "plain": "For every natural number ν ≥ 1 there exist periodic smooth divergence-free u₀ and a periodic smooth force f, decaying in time, such that no smooth global solution (v,p) has both v and p spatially 1-periodic."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1", "plain": "For every ν > 0 there are a force f ∈ C_c^∞(ℝ³×(0,∞)) and a smooth solution on [0,1) with zero initial datum, compact support, bounded L² norm and L^∞ blowup as t↑1. Consequently there is no smooth global solution with bounded energy, which gives alternative (C)."},
  {"ref": "Corollary 10.6", "plain": "For every ν > 0 there is a smooth force on T³, compactly supported in time, for which there is no global smooth periodic solution with zero initial datum. This gives alternative (D)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1.1 (consequence / alternative C)", "lean_theorem": "navier_stokes_breakdown_R3", "relation": "equivalent", "why": "This is Fefferman's (C) for every real ν > 0. The detailed blowup structure on [0,1) is not formalized; only the non-existence consequence is."},
  {"paper_ref": "Corollary 10.6 (alternative D)", "lean_theorem": "navier_stokes_breakdown_periodic", "relation": "lean_weaker", "why": "The Lean theorem covers only ν ∈ ℕ, ν ≥ 1, rather than every real ν > 0."},
  {"paper_ref": "Theorem 1.1 (blowup on [0,1), compact support)", "lean_theorem": null, "relation": "not_formalized", "why": "Only the breakdown consequence is stated in Lean."}
 ],
 "flags": [
  {"id": "F1", "category": "quantifier", "severity": "high", "decl": "navier_stokes_breakdown_periodic", "line": 280, "paper_ref": "Corollary 10.6", "explanation": "The viscosity is typed `nu : ℕ` and coerced to ℝ. The theorem therefore only asserts breakdown for ν = 1, 2, 3, …, not for every real ν > 0 as the paper and Fefferman's (D) state. This is inconsistent with the ℝ³ version, where `nu : ℝ`.", "polarity": "lean weaker", "probe_idea": "Restate with `(nu : ℝ) (hnu : nu > 0)` and check that the submitted proof still goes through."},
  {"id": "F2", "category": "assumption", "severity": "low", "decl": "NavierStokesExistenceAndSmoothnessPeriodic", "line": 269, "paper_ref": "Corollary 10.6", "explanation": "Requiring the pressure to be periodic adds a condition inside ¬∃. That makes the non-existence claim slightly weaker than the original Fefferman (D), which did not require periodic pressure. It matches the Clay errata, and the paper's own construction has compactly supported pressure.", "polarity": "lean weaker", "probe_idea": null}
 ],
 "lint_verdicts": [
  {"line": 81, "rule": "junk-deriv", "verdict": "harmless", "why": "Divergence is only applied to smooth fields, so fderiv takes its true value."},
  {"line": 155, "rule": "junk-div", "verdict": "harmless", "why": "The base 1+‖x‖ is ≥ 1, so the real power is positive and the division is genuine."},
  {"line": 155, "rule": "junk-deriv", "verdict": "harmless", "why": "u₀ is required to be ContDiff ∞, so iteratedFDeriv is genuine."},
  {"line": 191, "rule": "junk-div", "verdict": "harmless", "why": "The base 1+‖x‖+t is ≥ 1 for t ≥ 0."},
  {"line": 205, "rule": "junk-div", "verdict": "harmless", "why": "The base 1+t is ≥ 1 for t ≥ 0."},
  {"line": 224, "rule": "nat-sub", "verdict": "harmless", "why": "The subtraction is in ℝ³ (vectors), not ℕ."},
  {"line": 223, "rule": "junk-deriv", "verdict": "harmless", "why": "velocity_smooth on univ ×ˢ Ici 0 makes the spatial fderiv and the one-sided time derivativeWithin genuine; Ici 0 is unique-diff at every t ≥ 0."},
  {"line": 253, "rule": "junk-integral", "verdict": "harmless", "why": "The separate MemLp 2 hypothesis guarantees that ∫‖v‖² is a real integral, not the junk value 0."}
 ]
